154	    private void crewPools(String sheetId, Map<String, List<PoolMemberResponse>> members,
155	            Map<String, BigDecimal> totals) {
156	        Map<String, List<Object[]>> crews = new LinkedHashMap<>();
157	        jdbc.query("SELECT c.name, p.id, p.name, p.retired_from IS NOT NULL FROM crew c "
158	                + "LEFT JOIN person p ON p.id = c.lead_id AND p.sheet_id = c.sheet_id "
159	                + "WHERE c.sheet_id = ? ORDER BY c.position", rs -> {
160	                    List<Object[]> list = new ArrayList<>();
161	                    if (rs.getString(3) != null) list.add(new Object[] { rs.getLong(2), rs.getString(3), rs.getBoolean(4) });
162	                    crews.put(rs.getString(1), list);
163	                }, sheetId);
164	        jdbc.query("SELECT m.crew, p.id, p.name, p.retired_from IS NOT NULL FROM crew_member m "
165	                + "JOIN person p ON p.id = m.person_id WHERE m.sheet_id = ? ORDER BY m.position", rs -> {
166	                    List<Object[]> list = crews.get(rs.getString(1));
167	                    if (list != null) list.add(new Object[] { rs.getLong(2), rs.getString(3), rs.getBoolean(4) });
