169	        crews.forEach((name, people) -> {
170	            if (members.containsKey(name)) return;
171	            List<PoolMemberResponse> list = new ArrayList<>();
172	            BigDecimal total = BigDecimal.ZERO.setScale(2);
173	            if (!people.isEmpty()) {
174	                BigDecimal each = FULL.divide(BigDecimal.valueOf(people.size()), 2, RoundingMode.HALF_EVEN);
175	                BigDecimal first = FULL.subtract(each.multiply(BigDecimal.valueOf(people.size() - 1)));
176	                for (int i = 0; i < people.size(); i++) {
177	                    Object[] person = people.get(i);
178	                    BigDecimal share = i == 0 ? first : each;
179	                    list.add(new PoolMemberResponse((Long) person[0], (String) person[1], share.toPlainString(),
180	                            (Boolean) person[2], null, null, null, null, true));
