189	    /** Shares the pool's pot (null for none) among its members, then each member pool's cut among its own. */
190	    private static void share(String name, BigDecimal pot, Map<String, List<PoolMemberResponse>> members,
191	            Map<String, BigDecimal> totals, Set<Long> held, Map<String, List<PoolMemberResponse>> shown, int depth) {
192	        if (shown.containsKey(name) || depth > MAX_DEPTH) return;
193	        List<PoolMemberResponse> list = members.get(name);
194	        boolean balanced = totals.get(name).compareTo(FULL) == 0;
195	        List<PoolMemberResponse> withCuts = balanced && pot != null ? cuts(list, pot, held) : list;
196	        shown.put(name, withCuts);
197	        for (PoolMemberResponse m : withCuts) {
198	            if (m.pool() != null && members.containsKey(m.pool())) {
199	                share(m.pool(), m.cut() == null ? null : new BigDecimal(m.cut()), members, totals, held, shown, depth + 1);
200	            }
201	        }
202	    }
