204	    /** The members with their cuts of the pot. A retired member is left out of the cuts and a person
205	     *  with a hold in force on the sheet's today has none: each shows 0.00, their share spread over the
206	     *  others in proportion to those others' shares. When every member in their dates is retired, no
207	     *  member has a cut at all (null); each other member's is the pot times their share divided by
208	     *  the shares of the members with a cut added up, rounded half to even to two decimals. The
209	     *  remainder, the pot less the cuts, goes to the member with the smallest non-zero cut, the latest
210	     *  added on a tie (the last member with a cut when every cut is 0.00), so the cuts total the pot
211	     *  (when no member has a cut, each is 0.00). A member out of their dates is left out: no cut at all (null). */
212	    private static List<PoolMemberResponse> cuts(List<PoolMemberResponse> members, BigDecimal pot, Set<Long> held) {
213	        boolean allRetired = members.stream().anyMatch(PoolMemberResponse::current)
214	                && members.stream().filter(PoolMemberResponse::current).allMatch(PoolMemberResponse::retired);
215	        if (allRetired) {
216	            List<PoolMemberResponse> none = new ArrayList<>(members.size());
217	            for (PoolMemberResponse m : members) {
218	                none.add(new PoolMemberResponse(m.personId(), m.name(), m.share(), m.retired(), null, m.pool(),
219	                        m.from(), m.to(), m.current()));
220	            }
221	            return none;
222	        }
223	        BigDecimal[] cuts = new BigDecimal[members.size()];
224	        boolean[] cut = new boolean[members.size()];
225	        BigDecimal shares = BigDecimal.ZERO;
226	        for (int i = 0; i < members.size(); i++) {
227	            PoolMemberResponse m = members.get(i);
228	            cut[i] = m.current() && !m.retired() && (m.personId() == null || !held.contains(m.personId()));
229	            if (cut[i]) shares = shares.add(new BigDecimal(m.share()));
230	        }
231	        BigDecimal sum = BigDecimal.ZERO.setScale(2);
232	        int smallest = -1;
233	        int last = -1;
234	        for (int i = 0; i < members.size(); i++) {
235	            PoolMemberResponse m = members.get(i);
236	            BigDecimal share = new BigDecimal(m.share());
237	            cuts[i] = !cut[i] || shares.signum() == 0 ? BigDecimal.ZERO.setScale(2)
238	                    : pot.multiply(share).divide(shares, 2, RoundingMode.HALF_EVEN);
239	            sum = sum.add(cuts[i]);
240	            if (cut[i] && shares.signum() != 0) {
241	                last = i;
242	                if (cuts[i].signum() != 0 && (smallest < 0 || cuts[i].compareTo(cuts[smallest]) <= 0)) smallest = i;
243	            }
244	        }
245	        int to = smallest >= 0 ? smallest : last;
246	        if (to >= 0) cuts[to] = cuts[to].add(pot.subtract(sum));
247	        List<PoolMemberResponse> withCuts = new ArrayList<>(members.size());
248	        for (int i = 0; i < members.size(); i++) {
249	            PoolMemberResponse m = members.get(i);
250	            withCuts.add(new PoolMemberResponse(m.personId(), m.name(), m.share(), m.retired(),
251	                    m.current() ? cuts[i].toPlainString() : null, m.pool(), m.from(), m.to(), m.current()));
252	        }
253	        return withCuts;
254	    }
