480	    /** Refuses a pool already a member of a pool, one that would contain itself through any chain, and
481	     *  one that would make a chain of pools more than {@link Pools#MAX_DEPTH} deep. */
482	    private static void validatePool(String sheetId, String pool, String memberPool, Pools pools)
483	            throws InvalidSheetRequestException {
484	        if (pools.parentOf(sheetId, memberPool) != null) {
485	            throw new InvalidSheetRequestException(memberPool + " is already a member of a pool");
486	        }
487	        // The pools above, the pool itself among them.
488	        int above = 0;
489	        for (String p = pool; p != null && above <= Pools.MAX_DEPTH; p = pools.parentOf(sheetId, p)) {
490	            if (p.equals(memberPool)) {
491	                throw new InvalidSheetRequestException(memberPool + " cannot contain itself");
492	            }
493	            above++;
494	        }
495	        if (above + height(sheetId, memberPool, pools, 0) > Pools.MAX_DEPTH) {
496	            throw new InvalidSheetRequestException("A chain of pools is at most " + Pools.MAX_DEPTH + " deep");
497	        }
498	    }
499	
500	    /** How many pools deep the chain below the pool runs, the pool itself counted. */
501	    private static int height(String sheetId, String pool, Pools pools, int depth) {
502	        if (depth > Pools.MAX_DEPTH) return depth;
503	        int most = 0;
504	        for (String m : pools.memberPools(sheetId, pool)) most = Math.max(most, height(sheetId, m, pools, depth + 1));
505	        return 1 + most;
506	    }
507	}
