883	/** A pool's member as the server sends it: the person (or, for a member that is another pool, null
884	 *  and that pool's name in `pool`), their share (two decimals) and whether they are retired (a
885	 *  retirement date set, whatever the date), and their cut of the pool's pot (two decimals; null when
886	 *  the pool is unbalanced or has no pot, or the member is out of their dates), their from- and
887	 *  to-dates (null when none) and whether those include the sheet's today (a member out of them is
888	 *  left out of the pool). A pool that is a member of none has the sheet's pot; one that is a member
889	 *  of another has its cut there. */
890	export type PoolMember = {
891	  personId: number | null;
892	  name: string;
893	  share: string;
894	  retired: boolean;
895	  cut: string | null;
896	  pool: string | null;
897	  from: string | null;
898	  to: string | null;
899	  current: boolean;
900	};
901	
902	/** A pool as the server sends it: its name, its members in the order added, the total of their
903	 *  shares (two decimals; a retired member's counts as given), whether it is exactly 100.00 and
904	 *  whether it is a crew's (listed after the pools: the lead and the members at equal shares of
905	 *  100.00, the remainder on the lead; its members come from the crew, not the pool's form). */
906	export type Pool = { name: string; members: PoolMember[]; totalShare: string; balanced: boolean; crew: boolean };
907	
908	/** A share percent: up to two decimals. */
909	export const SHARE = /^\d{1,3}(\.\d{1,2})?$/;
910	
911	export const poolsKey = (sheet: string) => ['sheet', sheet, 'pools'] as const;
912	
913	/** The sheet's pools, in the order added, re-read whenever the sheet is loaded. */
914	export function usePools(sheet: string) {
915	  const [asOf] = useAsOf();
916	  return useQuery({
917	    queryKey: asOfKey(poolsKey(sheet), asOf),
918	    queryFn: () => getJson<Pool[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/pools`, asOf)),
919	    staleTime: 0,
920	    gcTime: 0,
921	  });
922	}
923	
924	/** The cuts of the person members of `pools` (just `personId`'s when given) added up, in cents; a
925	 *  pool member that is another pool, or a member with no cut, adds nothing. */
926	export function cutTotalCents(pools: Pool[], personId?: number): bigint {
927	  return pools
928	    .flatMap((p) => p.members)
929	    .filter((m) => m.personId !== null && m.cut !== null && (personId === undefined || m.personId === personId))
930	    .reduce((sum, m) => sum + hundredths(m.cut as string), 0n);
931	}
