import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { usePeople, type Person } from '../people/usePeople';
import { poolsKey, usePools, SHARE, type Pool } from './usePools';

/**
 * The sheet's pools and a form to add one by name (trimmed; a blank name, or one already a pool, is
 * refused). Each pool's row adds a member: a person with a share percent, more than 0.00 and at most
 * 100.00 with up to two decimals; a person already in the pool, or a bad share, is refused. A pool
 * shows its total share and whether it is balanced (exactly 100.00); a retired member's share counts
 * as given, but it is spread over the other members' cuts (none when every member is retired).
 * A member may be another pool, chosen as pool:<name>: a pool is a member of at most one pool, cannot
 * contain itself through any chain, and a chain of pools is at most three deep (the server refuses).
 * Each member of a balanced pool shows their cut of the pool's pot; unbalanced, or no pot, none. A pool
 * that is a member of none has the sheet's pot; one that is a member of another has its cut there.
 * A membership may carry a from-date and a to-date (both optional; a to-date before the from-date is
 * refused); a member whose dates do not include the sheet's today is left out: no share in the total,
 * no cut.
 */
function PoolsPanel({ user, sheet }: { user: string; sheet: string }) {
  const queryClient = useQueryClient();
  const { data: pools = [] } = usePools(sheet);
  const { data: people = [] } = usePeople(sheet);
  const [name, setName] = useState('');
  const [invalid, setInvalid] = useState(false);

  const submitOnce = useSubmitOnce();
  const add = useMutation({
    mutationFn: (n: string) => postJson<Pool[]>(`/api/sheets/${encodeURIComponent(sheet)}/pools`, { name: n, user }),
    onSuccess: async () => {
      setName('');
      await queryClient.invalidateQueries({ queryKey: poolsKey(sheet) });
    },
  });

  // An error goes as soon as its form is changed or submitted again.
  const clearError = () => {
    add.reset();
    setInvalid(false);
  };

  return (
    <section data-testid="pools-panel">
      <h2>Pools</h2>
      <form
        data-testid="pool-form"
        onSubmit={(e) => {
          e.preventDefault();
          const n = name.trim();
          if (n === '' || pools.some((p) => p.name === n)) {
            // Refused here, before anything is sent: the store and the audit file are untouched.
            add.reset();
            setInvalid(true);
            return;
          }
          setInvalid(false);
          submitOnce(() => add.mutateAsync(n));
        }}
      >
        <input
          data-testid="pool-form-name"
          aria-label="Pool name"
          placeholder="name"
          value={name}
          onChange={(e) => {
            setName(e.target.value);
            clearError();
          }}
        />{' '}
        <button type="submit" data-testid="pool-form-submit" disabled={add.isPending}>
          Add pool
        </button>
        {(invalid || add.isError) && (
          <span data-testid="pool-form-error" role="alert">
            {' '}
            {invalid ? 'Enter a name not already a pool.' : 'Could not add this pool.'}
          </span>
        )}
      </form>
      <table data-testid="pool-list">
        <tbody>
          {pools.map((p) => (
            <PoolRow key={p.name} user={user} sheet={sheet} pool={p} pools={pools} people={people} />
          ))}
        </tbody>
      </table>
    </section>
  );
}

/** A pool's row: its total share, balanced, its members with their shares, and a form to add one. */
function PoolRow({
  user,
  sheet,
  pool,
  pools,
  people,
}: {
  user: string;
  sheet: string;
  pool: Pool;
  pools: Pool[];
  people: Person[];
}) {
  const queryClient = useQueryClient();
  // A person's id, or pool:<name> for another pool.
  const [personId, setPersonId] = useState('');
  const [share, setShare] = useState('');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [invalid, setInvalid] = useState(false);

  const submitOnce = useSubmitOnce();
  const add = useMutation({
    mutationFn: (m: { personId?: number; memberPool?: string; share: string; from: string | null; to: string | null }) =>
      postJson<Pool[]>(`/api/sheets/${encodeURIComponent(sheet)}/pools/members`, { pool: pool.name, ...m, user }),
    onSuccess: async () => {
      setPersonId('');
      setShare('');
      setFrom('');
      setTo('');
      await queryClient.invalidateQueries({ queryKey: poolsKey(sheet) });
    },
  });

  const clearError = () => {
    add.reset();
    setInvalid(false);
  };

  return (
    <tr data-testid={`pool-row-${pool.name}`}>
      <td data-testid="pool-name">{pool.name}</td>
      <td>
        total <span data-testid="pool-total-share">{pool.totalShare}</span>
      </td>
      <td>
        balanced <span data-testid="pool-balanced">{pool.balanced ? 'yes' : 'no'}</span>
      </td>
      <td>
        <ul>
          {pool.members.map((m) => (
            <li
              key={m.pool !== null ? `pool-${m.pool}` : m.personId}
              data-testid={`pool-member-${pool.name}-${m.pool !== null ? `pool-${m.pool}` : m.personId}`}
            >
              <span>{m.name}</span>{' '}
              <span data-testid="pool-share">{m.share}</span>{' '}
              <span data-testid="pool-cut">{m.cut ?? ''}</span>
              {m.from !== null || m.to !== null ? ` (${m.from ?? '…'} to ${m.to ?? '…'})` : ''}
              {m.retired ? ' (retired)' : ''}
              {m.current ? '' : ' (out of dates)'}
            </li>
          ))}
        </ul>
      </td>
      <td>
        {pool.crew ? (
          'crew'
        ) : (
        <form
          onSubmit={(e) => {
            e.preventDefault();
            const memberPool = personId.startsWith(POOL_PREFIX) ? personId.slice(POOL_PREFIX.length) : null;
            const id = Number(personId);
            const s = share.trim();
            const n = Number(s);
            const f = from.trim();
            const t = to.trim();
            if (
              personId === '' ||
              (memberPool === null
                ? pool.members.some((m) => m.personId === id)
                : memberPool === pool.name || pool.members.some((m) => m.pool === memberPool)) ||
              !SHARE.test(s) ||
              !(n > 0 && n <= 100) ||
              (f !== '' && !DATE.test(f)) ||
              (t !== '' && !DATE.test(t)) ||
              (f !== '' && t !== '' && t < f)
            ) {
              // Refused here, before anything is sent: the store and the audit file are untouched.
              add.reset();
              setInvalid(true);
              return;
            }
            setInvalid(false);
            submitOnce(() =>
              add.mutateAsync({
                ...(memberPool === null ? { personId: id } : { memberPool }),
                share: s,
                from: f === '' ? null : f,
                to: t === '' ? null : t,
              }),
            );
          }}
        >
          <select
            data-testid="pool-member-select"
            aria-label="Member"
            value={personId}
            onChange={(e) => {
              setPersonId(e.target.value);
              clearError();
            }}
          >
            <option value="">choose…</option>
            {people.map((p) => (
              <option key={p.id} value={String(p.id)}>
                {p.name}
              </option>
            ))}
            {pools.map((p) => (
              <option key={`pool-${p.name}`} value={POOL_PREFIX + p.name}>
                {POOL_PREFIX + p.name}
              </option>
            ))}
          </select>{' '}
          <input
            data-testid="pool-member-share"
            aria-label="Share percent"
            placeholder="0.00"
            value={share}
            onChange={(e) => {
              setShare(e.target.value);
              clearError();
            }}
          />{' '}
          <input
            data-testid="pool-member-from"
            aria-label="From date"
            placeholder="from yyyy-mm-dd"
            value={from}
            onChange={(e) => {
              setFrom(e.target.value);
              clearError();
            }}
          />{' '}
          <input
            data-testid="pool-member-to"
            aria-label="To date"
            placeholder="to yyyy-mm-dd"
            value={to}
            onChange={(e) => {
              setTo(e.target.value);
              clearError();
            }}
          />{' '}
          <button type="submit" data-testid="pool-member-add" disabled={add.isPending}>
            Add member
          </button>
          {(invalid || add.isError) && (
            <span data-testid="pool-error" role="alert">
              {' '}
              {invalid
                ? 'Choose a person or pool not already in the pool, with a share more than 0.00 and at most 100.00, and a to-date not before the from-date.'
                : 'Could not add this member (a pool is in at most one pool, never in itself, at most three deep).'}
            </span>
          )}
        </form>
        )}
      </td>
    </tr>
  );
}

/** A from- or to-date: yyyy-mm-dd. */
const DATE = /^\d{4}-\d{2}-\d{2}$/;

/** The member select's value for another pool. */
const POOL_PREFIX = 'pool:';

export const contribution = SheetPanels.fill({ order: 10, Component: PoolsPanel });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asOfKey, asOfPath, useAsOf } from '../asof/useAsOf';
import { hundredths } from '../rates/useRates';

/** A pool's member as the server sends it: the person (or, for a member that is another pool, null
 *  and that pool's name in `pool`), their share (two decimals) and whether they are retired (a
 *  retirement date set, whatever the date), and their cut of the pool's pot (two decimals; null when
 *  the pool is unbalanced or has no pot, or the member is out of their dates), their from- and
 *  to-dates (null when none) and whether those include the sheet's today (a member out of them is
 *  left out of the pool). A pool that is a member of none has the sheet's pot; one that is a member
 *  of another has its cut there. */
export type PoolMember = {
  personId: number | null;
  name: string;
  share: string;
  retired: boolean;
  cut: string | null;
  pool: string | null;
  from: string | null;
  to: string | null;
  current: boolean;
};

/** A pool as the server sends it: its name, its members in the order added, the total of their
 *  shares (two decimals; a retired member's counts as given), whether it is exactly 100.00 and
 *  whether it is a crew's (listed after the pools: the lead and the members at equal shares of
 *  100.00, the remainder on the lead; its members come from the crew, not the pool's form). */
export type Pool = { name: string; members: PoolMember[]; totalShare: string; balanced: boolean; crew: boolean };

/** A share percent: up to two decimals. */
export const SHARE = /^\d{1,3}(\.\d{1,2})?$/;

export const poolsKey = (sheet: string) => ['sheet', sheet, 'pools'] as const;

/** The sheet's pools, in the order added, re-read whenever the sheet is loaded. */
export function usePools(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(poolsKey(sheet), asOf),
    queryFn: () => getJson<Pool[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/pools`, asOf)),
    staleTime: 0,
    gcTime: 0,
  });
}

/** The cuts of the person members of `pools` (just `personId`'s when given) added up, in cents; a
 *  pool member that is another pool, or a member with no cut, adds nothing. */
export function cutTotalCents(pools: Pool[], personId?: number): bigint {
  return pools
    .flatMap((p) => p.members)
    .filter((m) => m.personId !== null && m.cut !== null && (personId === undefined || m.personId === personId))
    .reduce((sum, m) => sum + hundredths(m.cut as string), 0n);
}

